import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { appleConfiguration, createAppleClientSecret } from "../_shared/apple.ts";

const json = (body: unknown, status = 200) => new Response(JSON.stringify(body), {
  status,
  headers: {
    "Content-Type": "application/json",
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
    "Access-Control-Allow-Methods": "POST, OPTIONS"
  }
});

type StorageEntry = { name: string; id?: string | null; metadata?: unknown };
const MAX_AUTH_AGE_SECONDS = 10 * 60;
const MAX_STORAGE_FILES = 5000;
const MAX_STORAGE_FOLDERS = 1000;
const MAX_STORAGE_DEPTH = 8;
const UPSTREAM_TIMEOUT_MS = 10_000;

function jwtPayload(authorization: string) {
  try {
    const token = authorization.replace(/^Bearer\s+/i, "");
    const part = token.split(".")[1];
    if (!part) return null;
    const normalized = part.replace(/-/g, "+").replace(/_/g, "/");
    return JSON.parse(atob(normalized.padEnd(Math.ceil(normalized.length / 4) * 4, "=")));
  } catch {
    return null;
  }
}

async function listAllFiles(bucket: any, prefix: string) {
  const files: string[] = [];
  const pending = [prefix];
  let folders = 0;
  while (pending.length) {
    const folder = pending.pop()!;
    folders += 1;
    if (folders > MAX_STORAGE_FOLDERS) throw new Error("storage_folder_limit_exceeded");
    const depth = folder.split("/").filter(Boolean).length - prefix.split("/").filter(Boolean).length;
    if (depth > MAX_STORAGE_DEPTH) throw new Error("storage_depth_limit_exceeded");
    let offset = 0;
    for (;;) {
      const { data, error } = await bucket.list(folder, { limit: 1000, offset, sortBy: { column: "name", order: "asc" } });
      if (error) throw error;
      const entries = (data || []) as StorageEntry[];
      for (const entry of entries) {
        const fullPath = folder ? `${folder}/${entry.name}` : entry.name;
        if (entry.id) {
          files.push(fullPath);
          if (files.length > MAX_STORAGE_FILES) throw new Error("storage_file_limit_exceeded");
        } else {
          pending.push(fullPath);
        }
      }
      if (entries.length < 1000) break;
      offset += entries.length;
    }
  }
  return files;
}

Deno.serve(async (request) => {
  if (request.method === "OPTIONS") return new Response(null, { status: 204, headers: json(null).headers });
  if (request.method !== "POST") return json({ error: "method_not_allowed" }, 405);

  const authorization = request.headers.get("Authorization");
  if (!authorization) return json({ error: "unauthorized" }, 401);

  let payload: { confirm?: boolean };
  try {
    payload = await request.json();
  } catch {
    return json({ error: "invalid_json" }, 400);
  }
  if (payload.confirm !== true) return json({ error: "confirmation_required" }, 400);

  const supabaseUrl = Deno.env.get("SUPABASE_URL");
  const anonKey = Deno.env.get("SUPABASE_ANON_KEY");
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  if (!supabaseUrl || !anonKey || !serviceRoleKey) return json({ error: "server_not_configured" }, 503);

  const caller = createClient(supabaseUrl, anonKey, {
    global: { headers: { Authorization: authorization } },
    auth: { persistSession: false, autoRefreshToken: false }
  });
  const { data: userData, error: userError } = await caller.auth.getUser();
  const user = userData.user;
  if (userError || !user) return json({ error: "unauthorized" }, 401);
  const claims = jwtPayload(authorization);
  const authenticatedAt = Number(claims && claims.iat);
  const now = Math.floor(Date.now() / 1000);
  if (!Number.isFinite(authenticatedAt) || authenticatedAt > now + 60 || now - authenticatedAt > MAX_AUTH_AGE_SECONDS) {
    return json({ error: "recent_authentication_required" }, 401);
  }

  const admin = createClient(supabaseUrl, serviceRoleKey, {
    auth: { persistSession: false, autoRefreshToken: false }
  });

  try {
    const { data: refreshToken, error: authorizationError } = await admin
      .rpc("get_apple_authorization_for_deletion", { target_user_id: user.id });
    if (authorizationError) throw authorizationError;
    if (refreshToken) {
      const apple = appleConfiguration();
      if (!apple) return json({ error: "apple_revocation_not_configured" }, 503);
      const clientSecret = await createAppleClientSecret(apple);
      const revokeResponse = await fetch("https://appleid.apple.com/auth/revoke", {
        method: "POST",
        headers: { "Content-Type": "application/x-www-form-urlencoded" },
        body: new URLSearchParams({
          client_id: apple.clientId,
          client_secret: clientSecret,
          token: refreshToken,
          token_type_hint: "refresh_token"
        }),
        signal: AbortSignal.timeout(UPSTREAM_TIMEOUT_MS)
      });
      if (!revokeResponse.ok) throw new Error(`apple_revocation_failed:${revokeResponse.status}`);
    }
    const { error: cleanupError } = await admin
      .rpc("delete_apple_authorization", { target_user_id: user.id });
    if (cleanupError) throw cleanupError;
  } catch (error) {
    console.error("delete-account apple revocation", error);
    return json({ error: "apple_revocation_failed" }, 502);
  }

  const { error: deletionStartError } = await admin
    .rpc("begin_account_deletion", { target_user_id: user.id });
  if (deletionStartError) {
    console.error("delete-account lock", deletionStartError);
    return json({ error: "account_deletion_failed" }, 500);
  }

  try {
    for (const bucketName of ["profile-media", "review-media", "custom-covers"]) {
      const bucket = admin.storage.from(bucketName);
      const files = await listAllFiles(bucket, user.id);
      for (let index = 0; index < files.length; index += 1000) {
        const { error } = await bucket.remove(files.slice(index, index + 1000));
        if (error) throw error;
      }
      const remaining = await listAllFiles(bucket, user.id);
      if (remaining.length) throw new Error(`storage_cleanup_incomplete:${bucketName}`);
    }
  } catch (error) {
    console.error("delete-account storage cleanup", error);
    return json({ error: "storage_cleanup_failed" }, 500);
  }

  // Deleting the auth user invalidates refresh tokens and prevents new sessions.

  const { error: deleteError } = await admin.auth.admin.deleteUser(user.id);
  if (deleteError) return json({ error: "account_deletion_failed" }, 500);

  return new Response(null, { status: 204 });
});

import { SignJWT, createRemoteJWKSet, importPKCS8, jwtVerify } from "npm:jose@5.10.0";

export type AppleConfiguration = {
  clientId: string;
  keyId: string;
  teamId: string;
  privateKey: string;
};

export function appleConfiguration(): AppleConfiguration | null {
  const clientId = Deno.env.get("APPLE_CLIENT_ID") || "";
  const keyId = Deno.env.get("APPLE_KEY_ID") || "";
  const teamId = Deno.env.get("APPLE_TEAM_ID") || "";
  const privateKey = (Deno.env.get("APPLE_PRIVATE_KEY") || "").replace(/\\n/g, "\n");
  if (!clientId || !keyId || !teamId || !privateKey) return null;
  return { clientId, keyId, teamId, privateKey };
}

export async function createAppleClientSecret(config: AppleConfiguration) {
  const key = await importPKCS8(config.privateKey, "ES256");
  const now = Math.floor(Date.now() / 1000);
  return new SignJWT({})
    .setProtectedHeader({ alg: "ES256", kid: config.keyId })
    .setIssuer(config.teamId)
    .setSubject(config.clientId)
    .setAudience("https://appleid.apple.com")
    .setIssuedAt(now)
    .setExpirationTime(now + 300)
    .sign(key);
}

const appleJwks = createRemoteJWKSet(new URL("https://appleid.apple.com/auth/keys"));

export async function verifyAppleIdentityToken(identityToken: string, clientId: string) {
  const { payload } = await jwtVerify(identityToken, appleJwks, {
    issuer: "https://appleid.apple.com",
    audience: clientId,
    algorithms: ["RS256"]
  });
  if (typeof payload.sub !== "string" || !payload.sub) throw new Error("apple_subject_missing");
  return payload.sub;
}

const SUPPORT_EMAIL = "lorefysupport@gmail.com";
const baseUrl = "https://qsroxmltioxqozmykens.supabase.co/functions/v1/lorefy-public";
const IMAGE_HOSTS = new Set([
  "s3.anilist.co", "s4.anilist.co", "cdn.myanimelist.net", "myanimelist.net",
  "covers.openlibrary.org", "images.ranobedb.org", "uploads.mangadex.org", "books.google.com",
  "books.googleusercontent.com", "lh3.googleusercontent.com", "m.media-amazon.com", "media.kitsu.app",
  "images-na.ssl-images-amazon.com", "commons.wikimedia.org", "upload.wikimedia.org",
  "images.weserv.nl", "wsrv.nl", "archive.org", "ak-asset.jarir.com", "freewebnovel.com"
]);
const MAX_MEDIA_BYTES = 8 * 1024 * 1024;
const MAX_CATALOG_BYTES = 4 * 1024 * 1024;
const CATALOG_TARGETS: Record<string, string> = {
  "catalog-mangadex": "https://api.mangadex.org/manga",
  "catalog-mangadex-covers": "https://api.mangadex.org/cover",
  "catalog-openlibrary": "https://openlibrary.org/search.json",
  "catalog-openlibrary-editions": "https://openlibrary.org/works",
  "catalog-googlebooks": "https://www.googleapis.com/books/v1/volumes",
  "catalog-jikan": "https://api.jikan.moe/v4",
  "catalog-anilist": "https://graphql.anilist.co",
  "catalog-wikipedia": "https://en.wikipedia.org/w/api.php",
  "catalog-wikidata": "https://www.wikidata.org/w/api.php",
  "catalog-commons": "https://commons.wikimedia.org/w/api.php",
  "catalog-dc-fandom": "https://dc.fandom.com/api.php",
  "catalog-marvel-fandom": "https://marvel.fandom.com/api.php"
};

function corsHeaders() {
  return {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET,POST,HEAD,OPTIONS",
    "Access-Control-Allow-Headers": "authorization,apikey,content-type,accept",
    "Vary": "Origin"
  };
}

async function catalogProxy(request: Request, provider: string, url: URL) {
  const targetBase = CATALOG_TARGETS[provider];
  if (!targetBase) return new Response("Not Found", { status: 404, headers: corsHeaders() });
  const allowPost = provider === "catalog-anilist";
  if (!(request.method === "GET" || request.method === "HEAD" || (allowPost && request.method === "POST"))) {
    return new Response("Method Not Allowed", { status: 405, headers: corsHeaders() });
  }
  let body: string | undefined;
  if (request.method === "POST") {
    body = await request.text();
    if (new TextEncoder().encode(body).byteLength > 256 * 1024) {
      return new Response("Payload Too Large", { status: 413, headers: corsHeaders() });
    }
  }
  try {
    let target = targetBase;
    if (provider === "catalog-anilist") {
      target = targetBase;
    } else if (provider === "catalog-jikan") {
      const safePath = String(url.searchParams.get("path") || "").replace(/^\/+/, "");
      if (!/^(?:manga(?:\/\d+(?:\/(?:characters|pictures))?)?|characters(?:\/\d+\/pictures)?)$/.test(safePath)) {
        return new Response("Invalid catalog path", { status: 400, headers: corsHeaders() });
      }
      const search = new URLSearchParams(url.search);
      search.delete("path");
      target = targetBase + "/" + safePath + (search.toString() ? "?" + search.toString() : "");
    } else if (provider === "catalog-openlibrary-editions") {
      const workId = String(url.searchParams.get("work") || "").toUpperCase();
      if (!/^OL\d+W$/.test(workId)) return new Response("Invalid work id", { status: 400, headers: corsHeaders() });
      const search = new URLSearchParams(url.search);
      search.delete("work");
      target = targetBase + "/" + workId + "/editions.json" + (search.toString() ? "?" + search.toString() : "");
    } else if (provider === "catalog-dc-fandom" || provider === "catalog-marvel-fandom") {
      const action = String(url.searchParams.get("action") || "");
      const prop = String(url.searchParams.get("prop") || "");
      const generator = String(url.searchParams.get("generator") || "");
      const allowedProps = new Set(["pageimages", "images", "imageinfo"]);
      if (action !== "query" || !allowedProps.has(prop) || (generator && generator !== "search")) {
        return new Response("Invalid Fandom query", { status: 400, headers: corsHeaders() });
      }
      if (String(url.searchParams.get("titles") || "").length > 1800 ||
          String(url.searchParams.get("gsrsearch") || "").length > 120 ||
          !/^\d*$/.test(String(url.searchParams.get("pageids") || ""))) {
        return new Response("Invalid Fandom query", { status: 400, headers: corsHeaders() });
      }
      const search = new URLSearchParams(url.search);
      search.delete("origin");
      search.set("format", "json");
      target = targetBase + "?" + search.toString();
    } else {
      target = targetBase + (url.search || "");
    }
    const headers: Record<string, string> = { "Accept": "application/json" };
    if (body) headers["Content-Type"] = "application/json";
    // Open Library accepts the platform default but rejects this service's
    // explicit User-Agent on its editions endpoint. Keep the identity header
    // for the other catalog providers while allowing verified book editions.
    if (provider !== "catalog-openlibrary" && provider !== "catalog-openlibrary-editions") {
      headers["User-Agent"] = "Lorefy/1.0 (lorefysupport@gmail.com)";
    }
    const upstream = await fetch(target, {
      method: request.method === "HEAD" ? "GET" : request.method,
      headers,
      body,
      signal: AbortSignal.timeout(10000)
    });
    const bytes = await upstream.arrayBuffer();
    if (bytes.byteLength > MAX_CATALOG_BYTES) return new Response("Response Too Large", { status: 413, headers: corsHeaders() });
    return new Response(request.method === "HEAD" ? null : bytes, {
      status: upstream.status,
      headers: {
        ...corsHeaders(),
        "Content-Type": upstream.headers.get("content-type") || "application/json; charset=utf-8",
        "Cache-Control": "public, max-age=300",
        "X-Content-Type-Options": "nosniff"
      }
    });
  } catch (_) {
    return new Response("Catalog source unavailable", { status: 502, headers: corsHeaders() });
  }
}

function approvedImageUrl(value: string): URL | null {
  try {
    const url = new URL(value);
    const host = url.hostname.replace(/^www\./i, "").toLowerCase();
  const hostnameAllowed = IMAGE_HOSTS.has(host) || host.endsWith(".archive.org") || host.endsWith(".wikimedia.org") ||
      host.endsWith(".fandom.com") || host.endsWith(".wikia.nocookie.net");
    if (url.protocol !== "https:" || !hostnameAllowed) return null;
    return url;
  } catch (_) {
    return null;
  }
}

async function mediaProxy(request: Request, rawUrl: string) {
  const target = approvedImageUrl(rawUrl);
  if (!target) return new Response("Invalid image source", { status: 400 });
  let upstream: Response;
  try {
    upstream = await fetch(target, { redirect: "follow" });
  } catch (_) {
    return new Response("Image source unavailable", { status: 502 });
  }
  if (!upstream.ok || !approvedImageUrl(upstream.url)) return new Response("Image source unavailable", { status: 502 });
  const contentType = String(upstream.headers.get("content-type") || "").toLowerCase().split(";")[0];
  const length = Number(upstream.headers.get("content-length") || 0);
  if (!/^image\/(?:avif|jpeg|png|webp|gif)$/.test(contentType) || (length && length > MAX_MEDIA_BYTES)) {
    return new Response("Unsupported image", { status: 415 });
  }
  const body = request.method === "HEAD" ? null : await upstream.arrayBuffer();
  if (body && body.byteLength > MAX_MEDIA_BYTES) return new Response("Image too large", { status: 413 });
  return new Response(body, {
    headers: {
      "Content-Type": contentType,
      "Cache-Control": "public, max-age=86400, stale-while-revalidate=604800",
      "Access-Control-Allow-Origin": "*",
      "X-Content-Type-Options": "nosniff",
      "Vary": "Origin"
    }
  });
}

