import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { appleConfiguration, createAppleClientSecret, verifyAppleIdentityToken } from "../_shared/apple.ts";

const json = (body: unknown, status = 200) => new Response(JSON.stringify(body), {
  status,
  headers: {
    "Content-Type": "application/json",
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
    "Access-Control-Allow-Methods": "POST, OPTIONS"
  }
});

const isCode = (value: unknown): value is string =>
  typeof value === "string" && value.length >= 10 && value.length <= 4096;

Deno.serve(async (request) => {
  if (request.method === "OPTIONS") return new Response(null, { status: 204, headers: json(null).headers });
  if (request.method !== "POST") return json({ error: "method_not_allowed" }, 405);

  const authorization = request.headers.get("Authorization");
  if (!authorization) return json({ error: "unauthorized" }, 401);
  let payload: { authorizationCode?: unknown };
  try { payload = await request.json(); } catch { return json({ error: "invalid_json" }, 400); }
  if (!isCode(payload.authorizationCode)) return json({ error: "invalid_authorization_code" }, 400);

  const supabaseUrl = Deno.env.get("SUPABASE_URL");
  const anonKey = Deno.env.get("SUPABASE_ANON_KEY");
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  const apple = appleConfiguration();
  if (!supabaseUrl || !anonKey || !serviceRoleKey || !apple) return json({ error: "server_not_configured" }, 503);

  const caller = createClient(supabaseUrl, anonKey, {
    global: { headers: { Authorization: authorization } },
    auth: { persistSession: false, autoRefreshToken: false }
  });
  const { data: userData, error: userError } = await caller.auth.getUser();
  const user = userData.user;
  if (userError || !user) return json({ error: "unauthorized" }, 401);

  const linkedAppleIdentity = (user.identities || []).find((identity) => identity.provider === "apple");
  if (!linkedAppleIdentity) return json({ error: "apple_identity_required" }, 409);
  const linkedAppleSubject = linkedAppleIdentity.identity_data?.sub;
  if (typeof linkedAppleSubject !== "string" || !linkedAppleSubject) {
    return json({ error: "apple_identity_invalid" }, 409);
  }

  try {
    const clientSecret = await createAppleClientSecret(apple);
    const tokenResponse = await fetch("https://appleid.apple.com/auth/token", {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded" },
      body: new URLSearchParams({
        client_id: apple.clientId,
        client_secret: clientSecret,
        code: payload.authorizationCode,
        grant_type: "authorization_code"
      })
    });
    const tokens = await tokenResponse.json();
    if (!tokenResponse.ok || typeof tokens.refresh_token !== "string" || !tokens.refresh_token || typeof tokens.id_token !== "string") {
      console.error("apple token exchange", tokenResponse.status, tokens.error || "missing_refresh_token");
      return json({ error: "apple_token_exchange_failed" }, 502);
    }
    const appleSubject = await verifyAppleIdentityToken(tokens.id_token, apple.clientId);
    if (appleSubject !== linkedAppleSubject) return json({ error: "apple_identity_mismatch" }, 409);

    const admin = createClient(supabaseUrl, serviceRoleKey, {
      auth: { persistSession: false, autoRefreshToken: false }
    });
    const stored = await admin.rpc("store_apple_authorization", {
      target_user_id: user.id,
      refresh_token: tokens.refresh_token,
      apple_subject: appleSubject
    });
    if (stored.error) throw stored.error;
    return json({ registered: true });
  } catch (error) {
    console.error("apple authorization storage", error);
    return json({ error: "apple_authorization_storage_failed" }, 500);
  }
});

import { SignJWT, createRemoteJWKSet, importPKCS8, jwtVerify } from "npm:jose@5.10.0";

export type AppleConfiguration = {
  clientId: string;
  keyId: string;
  teamId: string;
  privateKey: string;
};

export function appleConfiguration(): AppleConfiguration | null {
  const clientId = Deno.env.get("APPLE_CLIENT_ID") || "";
  const keyId = Deno.env.get("APPLE_KEY_ID") || "";
  const teamId = Deno.env.get("APPLE_TEAM_ID") || "";
  const privateKey = (Deno.env.get("APPLE_PRIVATE_KEY") || "").replace(/\\n/g, "\n");
  if (!clientId || !keyId || !teamId || !privateKey) return null;
  return { clientId, keyId, teamId, privateKey };
}

export async function createAppleClientSecret(config: AppleConfiguration) {
  const key = await importPKCS8(config.privateKey, "ES256");
  const now = Math.floor(Date.now() / 1000);
  return new SignJWT({})
    .setProtectedHeader({ alg: "ES256", kid: config.keyId })
    .setIssuer(config.teamId)
    .setSubject(config.clientId)
    .setAudience("https://appleid.apple.com")
    .setIssuedAt(now)
    .setExpirationTime(now + 300)
    .sign(key);
}

const appleJwks = createRemoteJWKSet(new URL("https://appleid.apple.com/auth/keys"));

export async function verifyAppleIdentityToken(identityToken: string, clientId: string) {
  const { payload } = await jwtVerify(identityToken, appleJwks, {
    issuer: "https://appleid.apple.com",
    audience: clientId,
    algorithms: ["RS256"]
  });
  if (typeof payload.sub !== "string" || !payload.sub) throw new Error("apple_subject_missing");
  return payload.sub;
}

import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const APNS_PRODUCTION_URL = "https://api.push.apple.com/3/device";
const APNS_SANDBOX_URL = "https://api.sandbox.push.apple.com/3/device";

const json = (body: unknown, status = 200) => new Response(JSON.stringify(body), {
  status,
  headers: { "Content-Type": "application/json", "Cache-Control": "no-store" }
});

function base64Url(value: string | Uint8Array) {
  const bytes = typeof value === "string" ? new TextEncoder().encode(value) : value;
  let binary = "";
  for (const byte of bytes) binary += String.fromCharCode(byte);
  return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
}

function pemBytes(value: string) {
  const normalized = value.replace(/\\n/g, "\n");
  const encoded = normalized
    .replace(/-----BEGIN PRIVATE KEY-----/g, "")
    .replace(/-----END PRIVATE KEY-----/g, "")
    .replace(/\s+/g, "");
  return Uint8Array.from(atob(encoded), (character) => character.charCodeAt(0));
}

async function secureEqual(left: string, right: string) {
  const encoder = new TextEncoder();
  const [leftHash, rightHash] = await Promise.all([
    crypto.subtle.digest("SHA-256", encoder.encode(left)),
    crypto.subtle.digest("SHA-256", encoder.encode(right))
  ]);
  const leftBytes = new Uint8Array(leftHash);
  const rightBytes = new Uint8Array(rightHash);
  let difference = 0;
  for (let index = 0; index < leftBytes.length; index += 1) difference |= leftBytes[index] ^ rightBytes[index];
  return difference === 0 && left.length === right.length;
}

async function createApnsJwt(teamId: string, keyId: string, privateKey: string) {
  const header = base64Url(JSON.stringify({ alg: "ES256", kid: keyId }));
  const claims = base64Url(JSON.stringify({ iss: teamId, iat: Math.floor(Date.now() / 1000) }));
  const unsigned = `${header}.${claims}`;
  const key = await crypto.subtle.importKey(
    "pkcs8",
    pemBytes(privateKey),
    { name: "ECDSA", namedCurve: "P-256" },
    false,
    ["sign"]
  );
  const signature = await crypto.subtle.sign(
    { name: "ECDSA", hash: "SHA-256" },
    key,
    new TextEncoder().encode(unsigned)
  );
  return `${unsigned}.${base64Url(new Uint8Array(signature))}`;
}

type WebhookPayload = {
  type?: string;
  schema?: string;
  table?: string;
  record?: { id?: string; user_id?: string };
};

Deno.serve(async (request) => {
  if (request.method !== "POST") return json({ error: "method_not_allowed" }, 405);

  const webhookSecret = Deno.env.get("PUSH_WEBHOOK_SECRET") || "";
  const suppliedSecret = request.headers.get("x-lorefy-webhook-secret") || "";
  if (!webhookSecret || !suppliedSecret || !await secureEqual(webhookSecret, suppliedSecret)) {
    return json({ error: "unauthorized" }, 401);
  }

  let payload: WebhookPayload;
  try { payload = await request.json(); }
  catch { return json({ error: "invalid_json" }, 400); }
  if (payload.type !== "INSERT" || payload.schema !== "public" || payload.table !== "notifications") {
    return json({ error: "unsupported_webhook" }, 400);
  }

  const notificationId = String(payload.record?.id || "");
  const userId = String(payload.record?.user_id || "");
  if (!/^[0-9a-f-]{36}$/i.test(notificationId) || !/^[0-9a-f-]{36}$/i.test(userId)) {
    return json({ error: "invalid_notification" }, 400);
  }

  const supabaseUrl = Deno.env.get("SUPABASE_URL");
  const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY");
  const teamId = Deno.env.get("APNS_TEAM_ID");
  const keyId = Deno.env.get("APNS_KEY_ID");
  const privateKey = Deno.env.get("APNS_PRIVATE_KEY");
  const topic = Deno.env.get("APNS_BUNDLE_ID") || "com.lorefy.app";
  const environment = Deno.env.get("APNS_ENVIRONMENT") === "development" ? "development" : "production";
  if (!supabaseUrl || !serviceRoleKey || !teamId || !keyId || !privateKey) {
    return json({ error: "server_not_configured" }, 503);
  }

  const admin = createClient(supabaseUrl, serviceRoleKey, {
    auth: { persistSession: false, autoRefreshToken: false }
  });
  const [{ data: notification, error: notificationError }, { data: devices, error: deviceError }] = await Promise.all([
    admin.from("notifications")
      .select("id,user_id,kind,title,body,target_path,data,event_key")
      .eq("id", notificationId).eq("user_id", userId).maybeSingle(),
    admin.from("push_device_tokens")
      .select("id,token,environment")
      .eq("user_id", userId).eq("platform", "ios")
      .eq("environment", environment)
      .order("last_seen_at", { ascending: false }).limit(20)
  ]);
  if (notificationError || deviceError) return json({ error: "notification_lookup_failed" }, 502);
  if (!notification) return json({ error: "notification_not_found" }, 404);
  if (!devices?.length) return json({ delivered: 0, unavailable: 0 }, 202);

  let authorization: string;
  try { authorization = await createApnsJwt(teamId, keyId, privateKey); }
  catch { return json({ error: "apns_key_invalid" }, 503); }

  const invalidDeviceIds: string[] = [];
  let delivered = 0;
  let unavailable = 0;
  await Promise.all(devices.map(async (device) => {
    const endpoint = device.environment === "development" ? APNS_SANDBOX_URL : APNS_PRODUCTION_URL;
    const response = await fetch(`${endpoint}/${encodeURIComponent(device.token)}`, {
      method: "POST",
      headers: {
        "Authorization": `bearer ${authorization}`,
        "Content-Type": "application/json",
        "apns-topic": topic,
        "apns-push-type": "alert",
        "apns-priority": "10",
        "apns-collapse-id": String(notification.event_key).slice(0, 64)
      },
      body: JSON.stringify({
        aps: {
          alert: { title: notification.title, body: notification.body },
          badge: 1,
          sound: "default"
        },
        notificationId: notification.id,
        kind: notification.kind,
        targetPath: notification.target_path,
        data: notification.data
      })
    });
    if (response.ok) { delivered += 1; return; }
    unavailable += 1;
    let reason = "";
    try { reason = String((await response.json())?.reason || ""); } catch {}
    if (response.status === 410 || ["BadDeviceToken", "Unregistered", "DeviceTokenNotForTopic"].includes(reason)) {
      invalidDeviceIds.push(device.id);
    }
  }));

  if (invalidDeviceIds.length) {
    await admin.from("push_device_tokens").delete().in("id", invalidDeviceIds);
  }
  return json({ delivered, unavailable }, 202);
});
